package com.hbm.client.radiolysis;
import com.hbm.client.model.*;import com.hbm.machine.radiolysis.*;import com.hbm.multiblock.DummyableBlock;import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.blockentity.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.phys.AABB;
/** Original smooth HFR model, all faces uncullled, exact source yaw180/0/90/270. */
public final class RadiolysisRenderer implements BlockEntityRenderer<RadiolysisBlockEntity> {
 static final ResourceLocation MODEL=RadiolysisContent.id("models/radiolysis.obj"),TEXTURE=RadiolysisContent.id("textures/models/radiolysis.png");
 public RadiolysisRenderer(BlockEntityRendererProvider.Context context){}
 static void inventory(PoseStack poses,MultiBufferSource buffers,int light,int overlay){var mesh=LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),MODEL);LegacyObjRenderer.renderAll(mesh,poses,buffers.getBuffer(RenderType.entityCutout(TEXTURE)),light,overlay,0xffffffff,LegacyObjRenderer.Convention.HFR);}
 @Override public void render(RadiolysisBlockEntity machine,float partial,PoseStack poses,MultiBufferSource buffers,int light,int overlay){int angle=switch(DummyableBlock.facing(machine.getBlockState())){case NORTH->180;case SOUTH->0;case WEST->90;default->270;};var mesh=LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),MODEL);LegacyContactShadows.render(machine,mesh,new org.joml.Matrix4f().translation(.5F,0,.5F).rotateY((float)Math.toRadians(angle)),poses,buffers);poses.pushPose();poses.translate(.5,0,.5);poses.mulPose(Axis.YP.rotationDegrees(angle));LegacyObjRenderer.renderAll(mesh,poses,buffers.getBuffer(RenderType.entityCutoutNoCull(TEXTURE)),light,overlay,0xffffffff,LegacyObjRenderer.Convention.HFR);poses.popPose();}
 @Override public boolean shouldRenderOffScreen(RadiolysisBlockEntity machine){return true;}@Override public int getViewDistance(){return 256;}@Override public AABB getRenderBoundingBox(RadiolysisBlockEntity machine){var pos=machine.getBlockPos();return new AABB(pos.getX()-1,pos.getY(),pos.getZ()-1,pos.getX()+2,pos.getY()+3,pos.getZ()+2);}
}
